begin;
select plan(10);
select ok(not has_table_privilege('authenticated','public.books_native_invoice_income_resolutions','select') and not has_table_privilege('anon','public.books_native_invoice_income_resolutions','select'),'coding cancellation evidence is private');
select ok(has_table_privilege('service_role','public.books_native_invoice_income_resolutions','select,insert'),'server may append coding cancellations');
select ok(not has_table_privilege('service_role','public.books_native_invoice_income_resolutions','update,delete'),'coding cancellations cannot be rewritten');
select ok(not has_function_privilege('authenticated','public.resolve_books_native_invoice_income(uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute'),'browser cannot invoke private income resolution');
select ok(has_function_privilege('service_role','public.resolve_books_native_invoice_income(uuid,uuid,uuid,uuid,uuid,jsonb,text)','execute') and not (select prosecdef from pg_proc where oid='public.resolve_books_native_invoice_income(uuid,uuid,uuid,uuid,uuid,jsonb,text)'::regprocedure),'server resolver retains invoker authority');
select ok((select relrowsecurity from pg_class where oid='public.books_native_invoice_income_resolutions'::regclass),'income cancellation has RLS enabled');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_income_resolutions'::regclass and tgname='books_native_invoice_income_resolution_guard'),'direct cancellation inserts enforce original scope and absent commit');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_income_selections'::regclass and tgname='aa_books_native_invoice_income_cancellation_guard'),'cancellation fence precedes source edits');
select ok(exists(select 1 from pg_constraint c join pg_attribute a on a.attrelid=c.conrelid and a.attnum=c.conkey[1] where c.conrelid='public.books_native_invoice_income_resolutions'::regclass and c.contype='u' and cardinality(c.conkey)=1 and a.attname='request_id'),'each income request has at most one permanent cancellation');
select ok(exists(select 1 from pg_trigger where tgrelid='public.books_native_invoice_income_resolutions'::regclass and tgname='books_native_invoice_income_resolution_immutable'),'coding cancellation history is immutable');
select * from finish();
rollback;
